     1	//! `std::cout << float`, which is glibc `printf("%g", (double) v)` at the
     2	//! default stream precision of 6.
     3	//!
     4	//! Every `f32` has a finite exact decimal expansion, so this expands the value
     5	//! exactly and then rounds that expansion to six significant digits. Working
     6	//! from the exact digits is what makes ties come out right: glibc rounds half
     7	//! to even, so `100000.5` prints as `100000` while `100001.5` prints as
     8	//! `100002`. Choosing `%e` or `%f` and trimming trailing zeros then follows
     9	//! the usual `%g` rules.
    10	
    11	use super::super::bignum::BigUint;
    12	
    13	/// Significant digits `%g` keeps at the default precision.
    14	const P: usize = 6;
    15	
    16	pub fn format_g6(v: f32) -> String {
    17	    if v.is_nan() {
    18	        return if v.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    19	    }
    20	    let sign = if v.is_sign_negative() { "-" } else { "" };
    21	    if v.is_infinite() {
    22	        return format!("{}inf", sign);
    23	    }
    24	
    25	    let bits = v.to_bits();
    26	    let frac = bits & 0x7f_ffff;
    27	    let biased = ((bits >> 23) & 0xff) as i32;
    28	    if biased == 0 && frac == 0 {
    29	        return format!("{}0", sign);
    30	    }
    31	    // |v| = m * 2^e with m an integer.
    32	    let (m, e) = if biased == 0 {
    33	        (frac, -149i32)
    34	    } else {
    35	        (frac | (1 << 23), biased - 127 - 23)
    36	    };
    37	
    38	    // Exact decimal expansion: |v| = digits * 10^scale.
    39	    let mut n = BigUint::from_u64(u64::from(m));
    40	    let scale = if e >= 0 {
    41	        n.shl_bits(e as u64);
    42	        0i64
    43	    } else {
    44	        n.mul_pow5((-e) as u32);
    45	        i64::from(e)
    46	    };
    47	    let ds = n.to_decimal_string();
    48	    let db = ds.as_bytes();
    49	
    50	    // Decimal exponent of the leading digit, then round to P digits.
    51	    let mut x = db.len() as i64 - 1 + scale;
    52	    let mut sig: Vec<u8> = Vec::with_capacity(P);
    53	    if db.len() <= P {
    54	        sig.extend_from_slice(db);
    55	        sig.resize(P, b'0');
    56	    } else {
    57	        sig.extend_from_slice(&db[..P]);
    58	        let next = db[P];
    59	        let rest_nonzero = db[P + 1..].iter().any(|&d| d != b'0');
    60	        let tie_up = rest_nonzero || (sig[P - 1] - b'0') % 2 == 1;
    61	        if next > b'5' || (next == b'5' && tie_up) {
    62	            round_up(&mut sig, &mut x);
    63	        }
    64	    }
    65	
    66	    let body = if x < -4 || x >= P as i64 {
    67	        // %e with precision P-1, trailing zeros trimmed.
    68	        let mut mant = String::new();
    69	        mant.push(sig[0] as char);
    70	        let f = trim_zeros(&sig[1..]);
    71	        if !f.is_empty() {
    72	            mant.push('.');
    73	            mant.push_str(&f);
    74	        }
    75	        format!("{}e{}{:02}", mant, if x < 0 { '-' } else { '+' }, x.abs())
    76	    } else if x >= 0 {
    77	        // %f with the point inside the digits we have.
    78	        let cut = x as usize + 1;
    79	        let int = String::from_utf8_lossy(&sig[..cut]).into_owned();
    80	        let f = trim_zeros(&sig[cut..]);
    81	        if f.is_empty() {
    82	            int
    83	        } else {
    84	            format!("{}.{}", int, f)
    85	        }
    86	    } else {
    87	        // %f with leading zeros between the point and the digits.
    88	        let mut fdigits = vec![b'0'; (-x - 1) as usize];
    89	        fdigits.extend_from_slice(&sig);
    90	        format!("0.{}", trim_zeros(&fdigits))
    91	    };
    92	    format!("{}{}", sign, body)
    93	}
    94	
    95	/// Increment the digit string, carrying; an all-nines string becomes 1 followed
    96	/// by zeros and bumps the exponent.
    97	fn round_up(sig: &mut Vec<u8>, x: &mut i64) {
    98	    for i in (0..sig.len()).rev() {
    99	        if sig[i] == b'9' {
   100	            sig[i] = b'0';
   101	        } else {
   102	            sig[i] += 1;
   103	            return;
   104	        }
   105	    }
   106	    sig.insert(0, b'1');
   107	    sig.truncate(P);
   108	    *x += 1;
   109	}
   110	
   111	fn trim_zeros(d: &[u8]) -> String {
   112	    let mut end = d.len();
   113	    while end > 0 && d[end - 1] == b'0' {
   114	        end -= 1;
   115	    }
   116	    String::from_utf8_lossy(&d[..end]).into_owned()
   117	}

  1	//! `std::stof`, i.e. glibc `strtof` behind libstdc++'s thin error wrapper.
  2	//!
  3	//! libstdc++ clears `errno`, calls `strtof`, and then maps the outcome:
  4	//! nothing converted becomes `std::invalid_argument`, `ERANGE` becomes
  5	//! `std::out_of_range`. Trailing garbage is *not* an error, so `"12abc"`
  6	//! yields 12.
  7	//!
  8	//! That makes three things load-bearing, and all three are reproduced here:
  9	//!
 10	//! 1. The full `strtof` grammar — leading whitespace, sign, decimal, C99 hex
 11	//!    floats, `inf`/`infinity`, `nan` with an optional `(n-char-sequence)` —
 12	//!    accepting the longest valid prefix and stopping there.
 13	//! 2. Correctly rounded conversion. Decimal goes through `std`'s parser, which
 14	//!    is correctly rounded; hex is converted here.
 15	//! 3. glibc's exact `ERANGE` rule. Overflow is simply "the rounded result is
 16	//!    infinite", but underflow has two quirks worth spelling out, both pinned
 17	//!    down against glibc:
 18	//!
 19	//!    * Whether a value counts as subnormal is decided *after* rounding its
 20	//!      significand to 24 bits at the value's own exponent. A value just under
 21	//!      `FLT_MIN` whose rounding carries into the normal range reports no
 22	//!      underflow, even though a value slightly smaller — which rounds to the
 23	//!      very same `FLT_MIN` — does report it.
 24	//!    * When denormalising, the dropped round bit alone is not a "lost bit".
 25	//!      Only bits strictly below it, or bits shifted out of the significand,
 26	//!      count. So a value a quarter of an ulp above a subnormal reports no
 27	//!      underflow while one an eighth of an ulp above it does.
 28	
 29	use super::super::bignum::BigUint;
 30	
 31	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 32	pub enum StofError {
 33	    /// No conversion could be performed (`std::invalid_argument`).
 34	    InvalidArgument,
 35	    /// The value was out of range for a `float` (`std::out_of_range`).
 36	    OutOfRange,
 37	}
 38	
 39	impl StofError {
 40	    /// The C++ exception class name, as the terminate handler prints it.
 41	    pub fn exception_name(self) -> &'static str {
 42	        match self {
 43	            StofError::InvalidArgument => "std::invalid_argument",
 44	            StofError::OutOfRange => "std::out_of_range",
 45	        }
 46	    }
 47	}
 48	
 49	/// `std::stof(str)`.
 50	pub fn stof(s: &str) -> Result<f32, StofError> {
 51	    let r = strtof(s.as_bytes());
 52	    if r.consumed == 0 {
 53	        return Err(StofError::InvalidArgument);
 54	    }
 55	    if r.erange {
 56	        return Err(StofError::OutOfRange);
 57	    }
 58	    Ok(r.value)
 59	}
 60	
 61	pub struct StrtofResult {
 62	    pub value: f32,
 63	    /// Bytes consumed; zero means no conversion (`endptr == nptr`).
 64	    pub consumed: usize,
 65	    /// Whether `strtof` would have set `errno` to `ERANGE`.
 66	    pub erange: bool,
 67	}
 68	
 69	fn is_space(c: u8) -> bool {
 70	    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
 71	}
 72	
 73	/// Case-insensitive prefix match; returns the match length.
 74	fn match_ci(b: &[u8], pat: &[u8]) -> Option<usize> {
 75	    if b.len() < pat.len() {
 76	        return None;
 77	    }
 78	    for (x, y) in b.iter().zip(pat) {
 79	        if x.to_ascii_lowercase() != *y {
 80	            return None;
 81	        }
 82	    }
 83	    Some(pat.len())
 84	}
 85	
 86	fn done(v: f32, neg: bool, consumed: usize, erange: bool) -> StrtofResult {
 87	    StrtofResult {
 88	        value: if neg { -v } else { v },
 89	        consumed,
 90	        erange,
 91	    }
 92	}
 93	
 94	pub fn strtof(b: &[u8]) -> StrtofResult {
 95	    let n = b.len();
 96	    let mut i = 0;
 97	    while i < n && is_space(b[i]) {
 98	        i += 1;
 99	    }
100	    let mut neg = false;
101	    if i < n && (b[i] == b'+' || b[i] == b'-') {
102	        neg = b[i] == b'-';
103	        i += 1;
104	    }
105	
106	    // "infinity" is tried first so the longer spelling wins.
107	    if let Some(len) = match_ci(&b[i..], b"infinity") {
108	        return done(f32::INFINITY, neg, i + len, false);
109	    }
110	    if let Some(len) = match_ci(&b[i..], b"inf") {
111	        return done(f32::INFINITY, neg, i + len, false);
112	    }
113	    if let Some(len) = match_ci(&b[i..], b"nan") {
114	        let mut j = i + len;
115	        if j < n && b[j] == b'(' {
116	            let mut k = j + 1;
117	            while k < n && (b[k].is_ascii_alphanumeric() || b[k] == b'_') {
118	                k += 1;
119	            }
120	            if k < n && b[k] == b')' {
121	                j = k + 1;
122	            }
123	        }
124	        return done(f32::NAN, neg, j, false);
125	    }
126	
127	    if i + 1 < n && b[i] == b'0' && (b[i + 1] == b'x' || b[i + 1] == b'X') {
128	        if let Some(r) = parse_hex(b, i + 2, neg) {
129	            return r;
130	        }
131	        // "0x" with no hex digit after it: glibc converts just the "0".
132	        return done(0.0, neg, i + 1, false);
133	    }
134	
135	    parse_dec(b, i, neg)
136	}
137	
138	/// Parse `[+-]?digits` for an exponent, clamping far outside any useful range
139	/// rather than overflowing.
140	fn parse_exp(b: &[u8], mut i: usize) -> Option<(i64, usize)> {
141	    let n = b.len();
142	    let mut neg = false;
143	    if i < n && (b[i] == b'+' || b[i] == b'-') {
144	        neg = b[i] == b'-';
145	        i += 1;
146	    }
147	    let start = i;
148	    while i < n && b[i].is_ascii_digit() {
149	        i += 1;
150	    }
151	    if i == start {
152	        return None;
153	    }
154	    let mut v: i64 = 0;
155	    for &d in &b[start..i] {
156	        if v < 1_000_000_000_000 {
157	            v = v * 10 + i64::from(d - b'0');
158	        }
159	    }
160	    Some((if neg { -v } else { v }, i))
161	}
162	
163	fn parse_dec(b: &[u8], start: usize, neg: bool) -> StrtofResult {
164	    let n = b.len();
165	    let mut i = start;
166	    let int_start = i;
167	    while i < n && b[i].is_ascii_digit() {
168	        i += 1;
169	    }
170	    let int_end = i;
171	    let mut frac_start = i;
172	    let mut frac_end = i;
173	    if i < n && b[i] == b'.' {
174	        i += 1;
175	        frac_start = i;
176	        while i < n && b[i].is_ascii_digit() {
177	            i += 1;
178	        }
179	        frac_end = i;
180	    }
181	    if int_end == int_start && frac_end == frac_start {
182	        return StrtofResult { value: 0.0, consumed: 0, erange: false };
183	    }
184	    let mut end = i;
185	    let mut exp: i64 = 0;
186	    if i < n && (b[i] == b'e' || b[i] == b'E') {
187	        if let Some((e, next)) = parse_exp(b, i + 1) {
188	            exp = e;
189	            end = next;
190	        }
191	    }
192	
193	    let mut digits: Vec<u8> = Vec::with_capacity((int_end - int_start) + (frac_end - frac_start));
194	    digits.extend_from_slice(&b[int_start..int_end]);
195	    digits.extend_from_slice(&b[frac_start..frac_end]);
196	    let mut k = exp - (frac_end - frac_start) as i64;
197	    // Normalise to significant digits: leading zeros are free, trailing zeros
198	    // move into the scale.
199	    let lead = digits.iter().take_while(|&&d| d == b'0').count();
200	    digits.drain(0..lead);
201	    while digits.last() == Some(&b'0') {
202	        digits.pop();
203	        k += 1;
204	    }
205	
206	    let (value, erange) = decimal_to_f32(&digits, k);
207	    done(value, neg, end, erange)
208	}
209	
210	/// Convert `digits * 10^k` (digits already normalised, no sign) to `f32`,
211	/// reporting whether glibc would set `ERANGE`.
212	fn decimal_to_f32(digits: &[u8], k: i64) -> (f32, bool) {
213	    if digits.is_empty() {
214	        return (0.0, false); // an exact zero never reports a range error
215	    }
216	    let mag = digits.len() as i64 - 1 + k; // floor(log10 V)
217	    if mag > 60 {
218	        return (f32::INFINITY, true); // far past FLT_MAX
219	    }
220	    if mag < -100 {
221	        return (0.0, true); // far below the smallest subnormal
222	    }
223	    let text = format!("{}e{}", std::str::from_utf8(digits).unwrap(), k);
224	    let value: f32 = text.parse().unwrap();
225	    if value.is_infinite() {
226	        return (value, true);
227	    }
228	    // Only a result at or below FLT_MIN can be an underflow, and deciding it
229	    // needs the exact value rather than the rounded one.
230	    let erange = value.abs() <= f32::MIN_POSITIVE && decimal_underflow(digits, k, mag);
231	    (value, erange)
232	}
