234	enum Q2 {
235	    TooSmall,
236	    TooLarge,
237	    Ok(u64),
238	}
239	
240	/// `floor(V * 2^(24-e))` must land in `[2^24, 2^25)` for `e` to be `V`'s own
241	/// binary exponent.
242	fn classify(q2: &BigUint) -> Q2 {
243	    match q2.to_u64() {
244	        None => Q2::TooLarge,
245	        Some(v) if v < 1 << 24 => Q2::TooSmall,
246	        Some(v) if v >= 1 << 25 => Q2::TooLarge,
247	        Some(v) => Q2::Ok(v),
248	    }
249	}
250	
251	/// `floor(V * 2^(24-e))` for `V = d * 10^-j`, with a flag for exactness.
252	///
253	/// `V * 2^(24-e) = d * 2^(24-e-j) / 5^j`, and chained floor divisions compose,
254	/// so dividing by `5^j` and by a power of two in either order is still exact.
255	fn extract_dec(d: &BigUint, j: u32, e: i64) -> (BigUint, bool) {
256	    let t = 24 - e - i64::from(j);
257	    let mut n = d.clone();
258	    if t >= 0 {
259	        n.shl_bits(t as u64);
260	        let exact = n.div_pow5(j);
261	        (n, exact)
262	    } else {
263	        let by_five = n.div_pow5(j);
264	        let by_two = n.shr_bits((-t) as u64);
265	        (n, by_five && by_two)
266	    }
267	}
268	
269	fn decimal_underflow(digits: &[u8], k: i64, mag: i64) -> bool {
270	    if k >= 0 {
271	        return false; // the value is an integer, so at least 1
272	    }
273	    let j = (-k) as u32;
274	    let d = BigUint::from_ascii_digits(digits);
275	    // log2(10) * mag lands within a few of the true exponent; the loop below
276	    // walks the rest of the way.
277	    let mut e = (mag as f64 * 3.321_928_094_887_362_f64).floor() as i64;
278	    loop {
279	        let (q2, exact) = extract_dec(&d, j, e);
280	        match classify(&q2) {
281	            Q2::TooSmall => e -= 1,
282	            Q2::TooLarge => e += 1,
283	            Q2::Ok(v) => {
284	                return glibc_underflow((v >> 1) as u32, e, v & 1 == 1, !exact);
285	            }
286	        }
287	    }
288	}
