290	/// glibc's underflow rule, given the truncated 24-bit significand `q` at
291	/// exponent `e` plus the round and sticky bits below it.
292	fn glibc_underflow(q: u32, e: i64, round: bool, sticky: bool) -> bool {
293	    let up = round && (sticky || q & 1 == 1);
294	    // Normal-vs-subnormal is decided after this rounding, so a carry out of
295	    // the significand escapes the report entirely.
296	    let e1 = if q + u32::from(up) == 1 << 24 { e + 1 } else { e };
297	    if e1 >= -126 {
298	        return false;
299	    }
300	    let shift = -126 - e1;
301	    if shift >= 24 {
302	        return true;
303	    }
304	    // The round bit itself does not count as a lost bit here — only bits
305	    // strictly below it, or bits shifted out of the significand.
306	    q & ((1u32 << shift) - 1) != 0 || sticky
307	}
