309	fn parse_hex(b: &[u8], start: usize, neg: bool) -> Option<StrtofResult> {
310	    let n = b.len();
311	    let mut i = start;
312	    let int_start = i;
313	    while i < n && b[i].is_ascii_hexdigit() {
314	        i += 1;
315	    }
316	    let int_end = i;
317	    let mut frac_start = i;
318	    let mut frac_end = i;
319	    if i < n && b[i] == b'.' {
320	        i += 1;
321	        frac_start = i;
322	        while i < n && b[i].is_ascii_hexdigit() {
323	            i += 1;
324	        }
325	        frac_end = i;
326	    }
327	    if int_end == int_start && frac_end == frac_start {
328	        return None;
329	    }
330	    let mut end = i;
331	    let mut pexp: i64 = 0;
332	    if i < n && (b[i] == b'p' || b[i] == b'P') {
333	        if let Some((e, next)) = parse_exp(b, i + 1) {
334	            pexp = e;
335	            end = next;
336	        }
337	    }
338	
339	    let mut digits: Vec<u8> = Vec::with_capacity((int_end - int_start) + (frac_end - frac_start));
340	    digits.extend_from_slice(&b[int_start..int_end]);
341	    digits.extend_from_slice(&b[frac_start..frac_end]);
342	    let m = BigUint::from_ascii_hex_digits(&digits);
343	    let he = pexp - 4 * (frac_end - frac_start) as i64;
344	
345	    let (value, erange) = hex_to_f32(&m, he);
346	    Some(done(value, neg, end, erange))
347	}
