370	/// Round the exact value described by `(q, e, round, sticky)` to `f32`, and
371	/// report `ERANGE`.
372	fn round_to_f32(q: u32, e: i64, round: bool, sticky: bool) -> (f32, bool) {
373	    let up = round && (sticky || q & 1 == 1);
374	    let mut q1 = q + u32::from(up);
375	    let mut e1 = e;
376	    if q1 == 1 << 24 {
377	        q1 >>= 1;
378	        e1 += 1;
379	    }
380	    if e1 > 127 {
381	        return (f32::INFINITY, true);
382	    }
383	    if e1 >= -126 {
384	        let bits = (((e1 + 127) as u32) << 23) | (q1 & 0x7f_ffff);
385	        return (f32::from_bits(bits), false);
386	    }
387	    let shift = -126 - e1;
388	    if shift >= 25 {
389	        return (0.0, true); // below half the smallest subnormal
390	    }
391	    let shift = shift as u32;
392	    let mask = (1u32 << shift) - 1;
393	    let lost = shift >= 24 || q & mask != 0 || sticky;
394	    let hi = q >> shift;
395	    let low = q & mask;
396	    let half = 1u32 << (shift - 1);
397	    let up2 = if low > half {
398	        true
399	    } else if low < half {
400	        false
401	    } else {
402	        round || sticky || hi & 1 == 1
403	    };
404	    // A subnormal significand of 2^23 encodes FLT_MIN, so no special case is
405	    // needed when rounding carries out of the subnormal range.
406	    (f32::from_bits(hi + u32::from(up2)), lost)
407	}
